def strategy(history, rng):
    n = len(history)
    if n == 0: return 'C'
    if n == 1: return 'C'
    if n == 2: return 'C'
    if n == 3: return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_D = me.count('D')
    opp_D = opp.count('D')
    last_my = me[-1]
    last_opp = opp[-1]
    remaining = 100 - n

    if n >= 2 and opp_D == n:
        return 'D'
    if n >= 3 and opp_D >= n - 1:
        return 'D'

    my_C_count = 0
    my_D_count = 0
    opp_C_after_my_C = 0
    opp_C_after_my_D = 0
    for i in range(n - 1):
        if me[i] == 'C':
            my_C_count += 1
            if opp[i + 1] == 'C':
                opp_C_after_my_C += 1
        else:
            my_D_count += 1
            if opp[i + 1] == 'C':
                opp_C_after_my_D += 1
    p_forgive = opp_C_after_my_D / my_D_count if my_D_count > 0 else 0.5
    p_recip = opp_C_after_my_C / my_C_count if my_C_count > 0 else 0.5

    recent_opp = opp[-5:] if n >= 5 else opp
    recent_opp_D = recent_opp.count('D')

    if remaining <= 1:
        return 'D'
    if remaining == 2:
        if p_forgive > 0.6 or opp_D == 0:
            return 'D'
        else:
            return 'C'
    if remaining == 3:
        if p_forgive > 0.7:
            return 'D'
        else:
            return 'C'

    if recent_opp_D >= 4:
        return 'D'
    if recent_opp_D >= 3 and p_forgive < 0.5:
        return 'D'

    if opp_D == 0:
        if my_D == 0:
            if n >= 4:
                return 'D'
            return 'C'
        else:
            allC_evidence = False
            for i in range(1, n):
                if me[i] == 'D' and me[i - 1] == 'D':
                    if i + 1 < n and opp[i + 1] == 'C':
                        allC_evidence = True
                        break
            if allC_evidence:
                return 'D'
            if n == 20 and my_D >= 3:
                return 'D'
            if n == 21 and last_my == 'D' and my_D >= 3:
                return 'D'
            if last_my == 'D':
                return 'C'
            else:
                if my_D * 100 < n * 15:
                    if n % 7 == 0:
                        return 'D'
                return 'C'
    else:
        if last_my == 'D':
            return 'C'
        if last_opp == 'D':
            return 'C'
        if p_forgive > 0.7:
            if my_D * 100 < n * 15 and n % 7 == 0:
                return 'D'
            return 'C'
        elif p_forgive > 0.4:
            if my_D * 100 < n * 10 and n % 10 == 0:
                return 'D'
            return 'C'
        else:
            return 'C'

    return 'C'
